 {let E=null;try{const n=$('L2 Count Plan');E=n.isExecuted?n.first().json.e340:null;}catch(e){E=null;}if(E&&E.version==='340'){const G=E.gloss||[];const NF=G.filter(x=>x.status==='NOT IN THE KJV RENDERINGS');out.push('[AUDIT v57: [L2] ENGLISH WORDS AND GLOSS TRIAL (ASK 340) -- PART A: '+(E.cand||[]).length+' English-word candidates; '+(E.ok?'':'NO ANSWER, nothing set aside ('+String(E.why||'').slice(0,200)+'); ')+(E.eng||[]).length+' set aside as English'+((E.eng||[]).length?' ('+E.eng.join(', ')+')':'')+'; '+(E.blocked||[]).length+' kept as lexicon transliterations'+((E.blocked||[]).length?' ('+E.blocked.join(', ')+')':'')+'; '+(E.not_kjv||[]).length+' not KJV words; '+(E.no_answer||[]).length+' no answer. PART B (record-only; nothing counted changes): '+G.length+' gloss parts checked; '+NF.length+' not found'+(NF.length?': '+NF.slice(0,12).map(x=>x.round+' GLOSS NOT IN THE KJV RENDERINGS: \''+x.part+'\' for '+x.num+' (KJV renders: '+(x.kjv||[]).join(', ')+')'+(x.lexicon?' [lexicon, not the KJV: '+x.lexicon+']':'')).join(' | '):'')+'; '+G.filter(x=>x.status==='LEXICON WORDING').length+' LEXICON WORDING (the Strong\'s lexicon, not the KJV); '+G.filter(x=>x.status==='REVIEW').length+' REVIEW; '+G.filter(x=>x.status==='NO ANSWER').length+' NO ANSWER.]');}} /* ASK 340 */
